import type { AutoSettings } from '../auto/types';

/** All money values are integer tiyin. Dates are ISO yyyy-mm-dd. */

export interface TaxTag {
  /** Tax report line id (see taxLines.ts) or null when the entry is not in the report. */
  line: string | null;
  nonDeductible?: boolean;
  /** true when the user picked the line by hand; auto-suggestions never overwrite it. */
  manual?: boolean;
}

export interface Entry {
  id: string;
  date: string;
  text: string;
  debit: string;
  credit: string;
  amount: number;
  tax?: TaxTag;
  /** Year-end closing entry generated by the app. */
  closing?: boolean;
  /** Entry built from uploaded documents; `edited` once the user changed it by hand. */
  auto?: { src: string; edited?: boolean };
}

export interface Opening {
  account: string;
  debit: number;
  credit: number;
}

export interface SubAccount {
  code: string;
  parent: string;
  name: string;
  stir?: string;
}

export interface Template {
  id: string;
  text: string;
  debit: string;
  credit: string;
  amount: number;
  day: number;
}

export interface Company {
  name: string;
  stir: string;
  address: string;
  director: string;
  accountant: string;
  taxOffice: string;
  /** Header of the official forms (soliq.uz); optional, older files lack them. */
  industry?: string;
  legalForm?: string;
  ownership?: string;
  ministry?: string;
  region?: string;
  codes?: CompanyCodes;
}

/** Classifier codes in the form header: KTUT (OKPO), IFUT (OKED), TXSHT (OKOPF), MShT (OKFS), DBIBT (SOOGU), MHOBT (SOATO). */
export interface CompanyCodes {
  ktut?: string;
  ifut?: string;
  txsht?: string;
  msht?: string;
  dbibt?: string;
  mxobt?: string;
}

export interface Doc {
  app: 'ochiq-hisob';
  version: 1;
  year: number;
  company: Company;
  opening: Opening[];
  entries: Entry[];
  subaccounts: SubAccount[];
  templates: Template[];
  /** Prior-year 2-shakl figures by line code (tiyin), filled on year roll-over or by hand. */
  prevYear: Record<string, number>;
  /** Profit tax rate in percent. */
  taxRate: number;
  /** Settings of entries built from uploaded documents (absent in older files). */
  auto?: AutoSettings;
  /** '1c' for documents on the 1C chart of accounts; older documents lack it (see migrate.ts). */
  chart?: '1c';
  /** Values typed into the official forms: "form:quarter" → line → column → value (tiyin, rates ×100). */
  forms?: Record<string, Record<string, Record<string, number>>>;
  /** Names of rows the filer names (overdue debtors, benefits, activity types): "form:quarter" → line → name. */
  formNames?: Record<string, Record<string, string>>;
}

export function emptyDoc(year: number): Doc {
  return {
    app: 'ochiq-hisob',
    version: 1,
    year,
    company: { name: '', stir: '', address: '', director: '', accountant: '', taxOffice: '', codes: {} },
    opening: [],
    entries: [],
    subaccounts: [],
    templates: [],
    prevYear: {},
    taxRate: 15,
    chart: '1c',
  };
}
